// Projection worker that handles OrderSubmitted events
async function handleOrderSubmitted(event: OrderSubmittedEvent) {
  const order = await orderRepo.findById(event.orderId);
  const customer = await customerRepo.findById(order.customerId);

  // Update the one shared dashboard read model
  await db.query(`
    UPDATE order_dashboard
    SET status = $1, customer_name = $2, account_manager = $3,
        total = $4, submitted_at = $5
    WHERE order_id = $6
  `, [order.status, customer.name, order.accountManagerName,
      order.total, event.timestamp, event.orderId]);

  // Also update the write-side orders table with display name for convenience
  await db.query(
    'UPDATE orders SET customer_display_name = $1 WHERE id = $2',
    [customer.name, event.orderId]
  );
}
